function CommissionerModal({value,events,onChange,onClose,onSave}:{value:Commissioner;events:Event[];onChange:(c:Commissioner)=>void;onClose:()=>void;onSave:(c:Commissioner)=>void}){const set=(key:keyof Commissioner,v:any)=>onChange({...value,[key]:v});return <div className="modalBackdrop"><form className="modal" onSubmit={e=>{e.preventDefault();if(value.name.trim()&&value.code.trim())onSave({...value,name:titleCase(value.name),code:value.code.trim().toUpperCase(),variants:value.variants.map(x=>x.toUpperCase())})}}><div className="modalHead"><div><small>GESTÃO DE COMISSÁRIO</small><h2>{value.name||"Novo comissário"}</h2></div><button type="button" onClick={onClose}>×</button></div><div className="formGrid"><label>NOME<input required value={value.name} onChange={e=>set("name",e.target.value)}/></label><label>CÓDIGO PRINCIPAL<input required value={value.code} onChange={e=>set("code",e.target.value)}/></label><label>VARIAÇÕES DO CÓDIGO<input value={value.variants.join(", ")} onChange={e=>set("variants",e.target.value.split(",").map(x=>x.trim()).filter(Boolean))} placeholder="COD1, COD-1, COD01"/></label><label>STATUS<select value={value.status} onChange={e=>set("status",e.target.value)}><option>Ativo</option><option>Inativo</option></select></label><label>TELEFONE<input value={value.phone} onChange={e=>set("phone",normalizePhone(e.target.value))}/></label><label>E-MAIL<input type="email" value={value.email} onChange={e=>set("email",normalizeEmail(e.target.value))}/></label><label>META DE INGRESSOS<input type="number" min="0" value={value.goal} onChange={e=>set("goal",Number(e.target.value))}/></label><label>COMISSÃO (%)<input type="number" min="0" step="0.01" value={value.commission} onChange={e=>set("commission",Number(e.target.value))}/></label></div><fieldset className="eventChecks"><legend>EVENTOS</legend>{events.map(e=><label key={e.id}><input type="checkbox" checked={value.eventIds.includes(e.id)} onChange={()=>set("eventIds",value.eventIds.includes(e.id)?value.eventIds.filter(id=>id!==e.id):[...value.eventIds,e.id])}/>{e.name}</label>)}</fieldset><label className="notesField">OBSERVAÇÕES<textarea value={value.notes} onChange={e=>set("notes",e.target.value)}/></label><div className="modalFoot"><button type="button" onClick={onClose}>Cancelar</button><button className="cta" type="submit">Salvar comissário</button></div></form></div>}
function Intelligence({data,stats,event}:{data:Store;stats:any[];event:Event}){const missing=stats.filter(c=>c.events>=2&&!c.sales.some((s:Sale)=>s.eventId===event.id));return <><div className="pageIntro"><h2>Insights que pedem ação.</h2><p>Todos os sinais abaixo são calculados a partir da base atual.</p></div><div className="insightGrid"><article><i>01</i><b>{missing.filter(c=>c.score>=71).length} clientes VIP ainda não compraram {event.label}.</b><p>Lista prioritária para ativação comercial.</p></article><article><i>02</i><b>{stats.filter(c=>c.early>=2&&!c.sales.some((s:Sale)=>s.eventId===event.id)).length} early buyers recorrentes estão ausentes.</b><p>O melhor momento de contato é agora.</p></article><article><i>03</i><b>Quinta, entre 18h e 22h, concentra o pico de compras.</b><p>Baseado no horário das vendas registradas.</p></article><article><i>04</i><b>OBOÉ e GINGA compartilham {affinity(data,"OBOÉ","GINGA")}% do público.</b><p>Alta afinidade para campanhas cruzadas.</p></article></div><article className="panel"><h3>Afinidade entre eventos</h3><div className="matrix"><span/><b>OBOÉ</b><b>GINGA</b><b>RETRONEJO</b>{["OBOÉ","GINGA","RETRONEJO"].flatMap(a=>[<b key={a}>{a}</b>,...["OBOÉ","GINGA","RETRONEJO"].map(b=><i key={a+b}>{a===b?100:affinity(data,a,b)}%</i>)] )}</div></article></>}
function affinity(data:Store,a:string,b:string){const ea=data.events.filter(e=>e.label===a).map(e=>e.id),eb=data.events.filter(e=>e.label===b).map(e=>e.id),ca=new Set(data.sales.filter(s=>ea.includes(s.eventId)).map(s=>s.clientId)),cb=new Set(data.sales.filter(s=>eb.includes(s.eventId)).map(s=>s.clientId));return Math.round([...ca].filter(x=>cb.has(x)).length/Math.max(1,ca.size)*100)}
function Mailing({segment,setSegment,count,exportList}:{segment:string;setSegment:(x:string)=>void;count:number;exportList:(x:"csv"|"xls")=>void}){return <><div className="pageIntro"><h2>Crie uma lista pronta para converter.</h2><p>Combine o segmento com a busca global e exporte o mailing.</p></div><article className="builder"><label>SEGMENTO<select value={segment} onChange={e=>setSegment(e.target.value)}>{["Todos","VIP","Early Buyers","Ainda não comprou","Adormecidos"].map(x=><option key={x}>{x}</option>)}</select></label><div className="result"><small>RESULTADO</small><b>{count}</b><span>clientes qualificados</span></div><div><button className="cta" onClick={()=>exportList("csv")}>Exportar CSV</button><button onClick={()=>exportList("xls")}>Exportar XLSX</button></div></article></>}
function Import({events,eventId,setEventId,onPick,loading,imports,onOpen,openId,onClose,onUndo,onClear}:{events:Event[];eventId:string;setEventId:(x:string)=>void;onPick:()=>void;loading:boolean;imports:ImportHistory[];onOpen:(x:string)=>void;openId:string|null;onClose:()=>void;onUndo:(x:string)=>void;onClear:()=>void}){const history=imports.filter(i=>i.eventId===eventId),selected=events.find(e=>e.id===eventId),opened=imports.find(i=>i.id===openId);return <><div className="pageIntro"><h2>Atualize a inteligência da TREND.</h2><p>Escolha o evento, envie CSV ou XLSX, revise o mapeamento e confirme somente depois da prévia.</p></div><article className="importTarget"><label>EVENTO DO MAILING<select value={eventId} onChange={e=>setEventId(e.target.value)}>{events.map(e=><option key={e.id} value={e.id}>{e.name} · {dt(e.date)}{e.lifecycle==="archived"?" · ARQUIVADO":""}</option>)}</select></label><span>ID interno: <b>{eventId}</b></span></article><button className="dropzone" onClick={onPick} disabled={loading||!eventId}>{loading?<><b>Processando...</b><span>Lendo e validando o arquivo</span></>:<><b>⇧ Escolher mailing CSV ou XLSX</b><span>Nenhum dado será salvo antes do mapeamento, da prévia e da sua confirmação.</span></>}</button><article className="panel importHistory"><div className="sectionHead"><div><small>RASTREABILIDADE</small><h2>Histórico de importações</h2></div><button className="riskButton" onClick={onClear} disabled={!selected}>Limpar mailing de {selected?.label}</button></div>{history.length?<div className="historyList">{history.map(i=><button key={i.id} onClick={()=>onOpen(i.id)}><span><b>{i.fileName}</b><small>{new Date(i.importedAt).toLocaleString("pt-BR")}</small></span><span>{i.total} registros</span><span>{i.added} novos</span><span>{i.duplicates} duplicados</span><i className={`historyStatus ${i.status.toLowerCase()}`}>{i.status}</i></button>)}</div>:<div className="empty compact"><b>Nenhuma importação para este evento</b><p>O histórico aparecerá aqui após a primeira confirmação.</p></div>}</article>{opened&&<div className="modalBackdrop"><article className="modal importDetail"><div className="modalHead"><div><small>DETALHES DA IMPORTAÇÃO</small><h2>{opened.fileName}</h2></div><button onClick={onClose}>×</button></div><p className="muted">{events.find(e=>e.id===opened.eventId)?.name} · {new Date(opened.importedAt).toLocaleString("pt-BR")}</p><div className="previewMetrics"><Metric label="REGISTROS" value={opened.total}/><Metric label="ADICIONADOS" value={opened.added}/><Metric label="DUPLICADOS" value={opened.duplicates}/><Metric label="ERROS" value={opened.errors}/></div>{opened.errorRows.length>0&&<div className="errorList">{opened.errorRows.slice(0,30).map(e=><p key={e.row}><b>Linha {e.row}</b>{e.reason}</p>)}</div>}<div className="modalFoot"><button onClick={onClose}>Fechar</button>{opened.status==="Concluída"&&<button className="riskButton" onClick={()=>onUndo(opened.id)}>Desfazer importação</button>}</div></article></div>}</>}
function ImportPreview({pending,setPending,preview,event,onCancel,onConfirm}:{pending:PendingImport;setPending:(p:PendingImport)=>void;preview:ReturnType<typeof analyzePending>;event:Event;onCancel:()=>void;onConfirm:()=>void}){const change=(i:number,key:FieldKey)=>setPending({...pending,mapping:pending.mapping.map((x,n)=>n===i?key:x)}),blocked=preview.missingColumns.length>0;return <div className="modalBackdrop"><article className="modal importPreview"><div className="modalHead"><div><small>MAPEAMENTO E PRÉVIA</small><h2>{pending.fileName}</h2></div><button onClick={onCancel}>×</button></div><p className="muted">Destino: <b>{event.name}</b> · {pending.format} · aba {pending.sheetName} · cabeçalho na linha {pending.headerRow+1}</p><div className="identifiedColumns"><b>Colunas identificadas</b><span>{preview.identified.join(" · ")||"Nenhuma coluna reconhecida"}</span></div>{blocked&&<div className="mappingWarning"><b>Revise antes de importar</b><span>Não reconhecemos: {preview.missingColumns.join(", ")}. Selecione manualmente a coluna correta abaixo.</span></div>}<div className="mappingGrid">{pending.headers.map((h,i)=><label key={`${h}-${i}`}><span>{h}</span><select value={pending.mapping[i]} onChange={e=>change(i,e.target.value as FieldKey)}>{FIELD_OPTIONS.map(f=><option key={f.key} value={f.key}>{f.label}</option>)}</select></label>)}</div><div className="previewMetrics seven"><Metric label="ENCONTRADOS" value={preview.total}/><Metric label="COM NOME" value={preview.withName}/><Metric label="SEM NOME" value={preview.withoutName}/><Metric label="VÁLIDOS" value={preview.valid}/><Metric label="NOVOS" value={preview.added}/><Metric label="DUPLICADOS" value={preview.duplicates}/><Metric label="ERROS" value={preview.errors}/></div><div className="previewTable"><div className="previewRow previewHead"><span>LINHA</span><span>CLIENTE</span><span>DATA</span><span>QTD.</span><span>VALOR</span><span>STATUS</span></div>{preview.rows.slice(0,12).map(r=><div className="previewRow" key={r.row}><span>{r.row}</span><span><b>{r.name||"Sem nome"}</b><small>{r.cpf||r.email||r.phone||"Sem identificador"}</small></span><span>{r.at?new Date(r.at).toLocaleString("pt-BR"):"—"}</span><span>{r.qty}</span><span>{money(r.value)}</span><span className={r.error?"rowError":r.duplicate?"rowDuplicate":"rowValid"}>{r.error||(r.duplicate?"Duplicado":"Válido")}</span></div>)}</div>{preview.errors>0&&<div className="errorList">{preview.rows.filter(r=>r.error).slice(0,20).map(r=><p key={r.row}><b>Linha {r.row}</b>{r.error}</p>)}</div>}<div className="modalFoot"><button onClick={onCancel}>Cancelar</button><button className="cta" onClick={onConfirm} disabled={blocked||!preview.added}>{blocked?"Corrija o mapeamento":`Confirmar ${preview.added} registros`}</button></div></article></div>}
function HowToImport(){const columns=["Nome","CPF","Telefone","E-mail","Nascimento","Cidade","Data da compra","Horário da compra","Quantidade","Valor","Tipo de ingresso","ID da venda"];return <><div className="pageIntro"><h2>Como importar</h2><p>O CRM aceita CSV e XLSX diretamente. A primeira aba do XLSX será lida e nenhum dado será salvo antes da sua confirmação.</p></div><div className="howGrid"><article className="panel"><small>FORMATOS ACEITOS</small><h3>CSV ou XLSX</h3><p>O cabeçalho pode estar depois de linhas de relatório. O sistema procura automaticamente a linha correta e ignora células vazias.</p></article><article className="panel"><small>IDENTIFICAÇÃO</small><h3>CPF → E-mail → Telefone</h3><p>Esses campos evitam clientes duplicados. Telefones e identificadores são tratados como texto para preservar zeros iniciais.</p></article><article className="panel"><small>VALIDAÇÃO</small><h3>Prévia obrigatória</h3><p>Confira colunas, exemplos, registros com e sem nome, duplicados e erros antes de confirmar.</p></article></div><article className="panel columnGuide"><div className="sectionHead"><div><small>PADRÃO RECOMENDADO</small><h2>Colunas do mailing</h2></div></div><div>{columns.map((c,i)=><span key={c}><b>{c}</b><small>{i===0||i===6?"Essencial":i===1||i===2||i===3?"Ao menos um":"Opcional"}</small></span>)}</div><p>Também reconhecemos variações como Nome Cliente, Nome Titular, Nome Participante, Celular, WhatsApp, E-mail Cliente, Data Venda, Pedido Data, Hora Venda, Valor Pago, Produto e Registro.</p></article></>}
function EventModal({value,onChange,onSave,onClose}:{value:Event;onChange:(e:Event)=>void;onSave:(e:Event)=>void;onClose:()=>void}){const set=(k:keyof Event,v:string|number)=>onChange({...value,[k]:v});return <div className="modalBackdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><form className="modal" onSubmit={e=>{e.preventDefault();onSave(value)}}><div className="modalHead"><div><small>{value.name?"EDITAR EVENTO":"NOVO EVENTO"}</small><h2>{value.name||"Criar evento"}</h2></div><button type="button" onClick={onClose}>×</button></div><div className="formGrid"><label>NOME<input required value={value.name} onChange={e=>set("name",e.target.value)} placeholder="Ex.: OBOÉ 4 ANOS"/></label><label>LABEL<input required value={value.label} onChange={e=>set("label",e.target.value.toUpperCase())} placeholder="Ex.: OBOÉ"/></label><label>DATA E HORA DO EVENTO<input required type="datetime-local" value={value.date} onChange={e=>set("date",e.target.value)}/></label><label>ABERTURA DAS VENDAS<input required type="datetime-local" value={value.opened} onChange={e=>set("opened",e.target.value)}/></label><label>LOCAL<input required value={value.venue} onChange={e=>set("venue",e.target.value)} placeholder="Ex.: Armazém Convention"/></label><label>CIDADE<input required value={value.city||""} onChange={e=>set("city",e.target.value)} placeholder="Ex.: Salvador"/></label><label>CAPACIDADE<input min="0" type="number" value={value.capacity||""} onChange={e=>set("capacity",+e.target.value)} placeholder="0"/></label><label>STATUS DE VENDAS<select value={value.status} onChange={e=>set("status",e.target.value)}>{["Vendas abertas","Vendas acelerando","Vendas abaixo da média","Perto de sold out","Sold out","Encerrado"].map(x=><option key={x}>{x}</option>)}</select></label></div><div className="idNotice"><b>ID interno permanente</b><span>{value.id}</span><p>Esse identificador nunca muda e protege os vínculos com clientes, vendas, mailings e históricos.</p></div><div className="modalFoot"><button type="button" onClick={onClose}>Cancelar</button><button className="cta" type="submit">Salvar evento</button></div></form></div>}
